import{_ as a,o as s,c as p,a2 as t}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E8%A1%A8%E7%BB%93%E6%9E%84%E5%8F%98%E6%9B%B4/Navicat.png",o="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E8%A1%A8%E7%BB%93%E6%9E%84%E5%8F%98%E6%9B%B4/%E7%BB%93%E6%9E%84%E5%90%8C%E6%AD%A5%E7%9A%84%E6%95%B0%E6%8D%AE%E5%BA%93.png",E="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E8%A1%A8%E7%BB%93%E6%9E%84%E5%8F%98%E6%9B%B4/%E7%BB%93%E6%9E%84%E5%90%8C%E6%AD%A5%E7%9A%84%E6%96%B0%E8%80%81%E6%95%B0%E6%8D%AE%E5%BA%93.png",l="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E8%A1%A8%E7%BB%93%E6%9E%84%E5%8F%98%E6%9B%B4/%E7%BB%93%E6%9E%84%E5%90%8C%E6%AD%A5%E7%9A%84%E9%80%89%E9%A1%B9.png",c="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E8%A1%A8%E7%BB%93%E6%9E%84%E5%8F%98%E6%9B%B4/%E7%BB%93%E6%9E%84%E5%90%8C%E6%AD%A5%E7%9A%84%E8%A1%A8%E6%9B%B4%E6%83%85%E5%86%B5.png",d="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E8%A1%A8%E7%BB%93%E6%9E%84%E5%8F%98%E6%9B%B4/%E7%BB%93%E6%9E%84%E5%90%8C%E6%AD%A5%E7%9A%84SQL%E5%8F%98%E6%9B%B4%E8%AF%AD%E5%8F%A5.png",r="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E8%A1%A8%E7%BB%93%E6%9E%84%E5%8F%98%E6%9B%B4/%E6%95%B0%E6%8D%AE%E5%90%8C%E6%AD%A5.png",u=JSON.parse('{"title":"表结构变更（版本升级）","description":"","frontmatter":{},"headers":[],"relativePath":"sql-update.md","filePath":"sql-update.md","lastUpdated":null}'),n={name:"sql-update.md"};function h(B,e,m,A,_,g){return s(),p("div",null,[...e[0]||(e[0]=[t('<h1 id="表结构变更-版本升级" tabindex="-1">表结构变更（版本升级） <a class="header-anchor" href="#表结构变更-版本升级" aria-label="Permalink to &quot;表结构变更（版本升级）&quot;">​</a></h1><p>系统每次发新版本，会伴随着数据库表结构、数据的变更。这个时候，我们可以通过 Navicat 提供的「结构同步」「数据同步」功能，来进行数据库的升级。</p><p><img src="'+i+'" alt="Navicat"></p><p>友情提示：</p><p>你自己的项目发布上线，如果涉及到数据库表结构的变更，也可以试试 Navicat 的「结构同步」「数据同步」功能。</p><p>我们之前项目，蛮多同学都是这么干的，避免漏字段！</p><h2 id="_1-结构同步" tabindex="-1">1. 结构同步 <a class="header-anchor" href="#_1-结构同步" aria-label="Permalink to &quot;1. 结构同步&quot;">​</a></h2><p>本小节，我们以 <code>2.0.0</code> 版本升级到 <code>2.1.0</code> 版本为例。需要先自己初始化对应的两个数据库，如下图所示：</p><p><img src="'+o+'" alt="结构同步的数据库"></p><p>① 点击 Navicat 的 [工具 -&gt; 结构同步] 菜单，配置源数据库是 <code>2.1.0</code>，目标数据库是 <code>2.0.0</code>，因为是将“新”应到“老”数据库。如下图所示：</p><p><img src="'+E+'" alt="结构同步的新老数据库"></p><p>② 点击左下角的 [选项] 按钮，取消掉“比较自动递增值”，因为我们不希望自增值也同步。如下图所示：</p><p><img src="'+l+'" alt="结构同步的选项"></p><p>③ 点击右下角的 [下一步] 按钮，可以看到每个表的表更情况（新增、修改、删除）。如下图所示：</p><p><img src="'+c+'" alt="结构同步的表更情况"></p><p>此时，如果你只想看部分表的变更，可以点击“源对象”下的选项，取消掉不需要同步的表。</p><p>④ 继续点击右下角的 [下一步] 按钮，可以看到具体的 SQL 变更语句。如下图所示：</p><p><img src="'+d+'" alt="结构同步的 SQL 变更语句"></p><p>注意，不要点击有效的 [开始] 按钮，而是将 SQL 语句复制出来，二次检查后，选择你需要的部分，手动执行变更！</p><p>友情提示：DataGrip 也提供类似功能，后面也可以尝试下。</p><p><a href="https://blog.csdn.net/qq_43780340/article/details/125872609" target="_blank" rel="noreferrer">《使用 datagrip 实现不同数据库表之间的结构同步》</a></p><h2 id="_2-数据同步" tabindex="-1">2. 数据同步 <a class="header-anchor" href="#_2-数据同步" aria-label="Permalink to &quot;2. 数据同步&quot;">​</a></h2><p>Navicat 的「数据同步」功能，和「结构同步」同步是一致的，只是在最后一步，会展示数据的变更情况（新增、修改、删除），这里就不重复演示了。</p><p><img src="'+r+`" alt="数据同步"></p><p>系统绝大多数表的数据变更不用关注，只需要关注偏 <strong>全局配置</strong> 的表，例如说：</p><ul><li>字段相关：<code>system_dict_type</code>、<code>system_dict_data</code></li><li>权限相关：<code>system_menu</code></li><li>邮件相关：<code>system_mail_template</code></li><li>短信相关：<code>system_sms_template</code></li><li>站内信相关：<code>system_notify_template</code></li></ul><h2 id="_3-数据库转换" tabindex="-1">3. 数据库转换 <a class="header-anchor" href="#_3-数据库转换" aria-label="Permalink to &quot;3. 数据库转换&quot;">​</a></h2><p>项目提供了 <code>sql/tools/convertor.py</code> 脚本，支持将 MySQL 转换为 Oracle、PostgreSQL、SQL Server、达梦、人大金仓、OpenGauss 等数据库的脚本。</p><p>疑问：什么时候需要转换数据库？</p><p>场景一：项目主要使用 MySQL 开发，其它数据库可能滞后，此时可以自己转换下。</p><p>场景二：项目类似 mall、bpm、ai、member、pay、crm、erp 等其它模块的数据库，只提供了 MySQL 的数据库脚本，此时也可以自己转换下。</p><h3 id="_3-1-实现原理" tabindex="-1">3.1 实现原理 <a class="header-anchor" href="#_3-1-实现原理" aria-label="Permalink to &quot;3.1 实现原理&quot;">​</a></h3><p>通过读取 MySQL 的 <code>sql/mysql/ruoyi-vue-pro.sql</code> 数据库文件，转换成对应的数据库脚本。</p><p>疑问：如果我想转换 mall、bpm、ai、member、pay、crm、erp 等其它模块的数据库，怎么办？</p><p>第一步，将对应的 SQL 拷贝到 <code>sql/mysql/</code> 目录下。</p><p>第二步，将 <code>convertor.py</code> 脚本中的 <code>ruoyi-vue-pro.sql</code> 变量，修改为对应的 SQL 文件。</p><h3 id="_3-2-如何使用" tabindex="-1">3.2 如何使用？ <a class="header-anchor" href="#_3-2-如何使用" aria-label="Permalink to &quot;3.2 如何使用？&quot;">​</a></h3><p>① 安装依赖库 <code>simple-ddl-parser</code></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> simple-ddl-parser</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pip3 install simple-ddl-parser</span></span></code></pre></div><p>② 在 <code>sql/tools/</code> 目录下，执行如下命令打印生成 postgres 的脚本内容，其他可选参数有：<code>oracle</code>、<code>sqlserver</code>、<code>dm8</code>、<code>kingbase</code>、<code>opengauss</code>：</p><div class="language-Bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> convertor.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># python3 convertor.py postgres &gt; tmp.sql</span></span></code></pre></div><p>程序将 SQL 脚本打印到终端，可以重定向到临时文件 <code>tmp.sql</code>。</p><p>确认无误后，可以利用 IDEA 进行格式化。当然，也可以直接导入到数据库中。</p>`,43)])])}const y=a(n,[["render",h]]);export{u as __pageData,y as default};
